SELECT id, customer_id, created_at, coupon_codes, items, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, COALESCE(attributes['device'], 'direct') AS device_or_default, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, x) -> acc + x.qty * x.price, acc -> ROUND(acc, 2)) AS cart_value, ARRAY_CONTAINS(MAP_KEYS(attributes), 'weight_kg') AS has_weight_kg FROM carts
